local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageCustomerInfoDialog.prefab > name: HeadNode
---@class OverseaManageCustomerHeadNode
---@field Env                           	OverseaManageCustomerHeadNode           
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgNew                        	UnityEngine.RectTransform               
---@field Lock                          	UnityEngine.RectTransform               
---@field ImgHead                       	UnityEngine.RectTransform               
---@field Select                        	UnityEngine.RectTransform               
---@field Button                        	UnityEngine.RectTransform               
local OverseaManageCustomerHeadNode = Class('OverseaManageCustomerHeadNode')
function OverseaManageCustomerHeadNode:__init()
    self.headData = nil
    self.index = nil
    self.callBack = nil
end

function OverseaManageCustomerHeadNode:__delete()
    self.headData = nil
    self.index = nil
    self.callBack = nil
end

function OverseaManageCustomerHeadNode:Awake()
    self:AddUIClick()
end

function OverseaManageCustomerHeadNode:AddUIClick()
    SetButtonAction(self.Button,Bind(self,self.OnHeadIconClick))
end

function OverseaManageCustomerHeadNode:OnHeadIconClick()
    CfUtils.PlayAnimation(self.controller.gameObject,"OverseaManageCustomerInfoDialog_Head_Selected")
    --KTool.SetActive(self.Select.gameObject,true)
    if not isNull(self.callBack) then
        self.callBack(self.index,self.headData,self.vo)
    end
end

function OverseaManageCustomerHeadNode:SetIndexAndCallBack(index,callBack)
    self.index = index
    self.callBack = callBack
end


function OverseaManageCustomerHeadNode:RefreshHeadNodeShow(data,index)
    self:DoSelect()
    self.headData = data
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting6071,"MaidCoffeeGuestCollectionVo",self.headData.visitorId)
    if isNull(vo) then
        printError("客人图鉴信息表 中不存在客人Id ---->>>> %s ，请检查 ！！！！")
        return
    end
    self.vo = vo
    CfUtils.FillImage(self.ImgHead,vo.image)

    local isUnLock = GameUtils.IsUnlockedSingle(vo.unlockType, vo.unlockNum, vo.unlockId)
    KTool.SetActive(self.Lock.gameObject,not isUnLock)

    if self.index == index then
        self:OnHeadIconClick()
    end
end

function OverseaManageCustomerHeadNode:RefreshRedPoint(status)
    local isUnLock = GameUtils.IsUnlockedSingle(self.vo.unlockType,self.vo.unlockNum ,self.vo.unlockId)
    if isUnLock then
        KTool.SetActive(self.ImgNew.gameObject,status)
    else
        KTool.SetActive(self.ImgNew.gameObject,false)
    end
end

function OverseaManageCustomerHeadNode:DoSelect()
    CfUtils.PlayAnimation(self.controller.gameObject,"OverseaManageCustomerInfoDialog_Head_Idle")
    --KTool.SetActive(self.Select.gameObject,false)
end

function OverseaManageCustomerHeadNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageCustomerHeadNode